func:
// Проверяем, что данные пришли
if (msg.payload) {
    // Выводим в лог то, что реально пришло от формы, чтобы проверить структуру
    node.warn("Form payload received: " + JSON.stringify(msg.payload));

    // Извлекаем значения универсально (поддерживаем разные варианты названий полей)
    let newTopic = msg.payload.topic || msg.payload['Topic Name'] || msg.payload.customTopic;
    let newThreshold = msg.payload.threshold || msg.payload['Alarm Threshold'];
    let newMultiplier = msg.payload.multiplier || msg.payload['Multiplier Factor'];

    // Если значения найдены, сохраняем их в контекст потока
    if (newTopic !== undefined && newTopic !== "") {
        flow.set("customTopic", String(newTopic));
    }
    if (newThreshold !== undefined && !isNaN(Number(newThreshold))) {
        flow.set("threshold", Number(newThreshold));
    }
    if (newMultiplier !== undefined && !isNaN(Number(newMultiplier))) {
        flow.set("multiplier", Number(newMultiplier));
    }
}

msg.payload = {
    status: "Updated successfully!",
    currentTopic: flow.get("customTopic"),
    currentThreshold: flow.get("threshold"),
    currentMultiplier: flow.get("multiplier")
};

return msg;
